using System;
using System.Linq;
using System.IO;
using System.Collections.Generic;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
namespace Underwater.Editor {
public static class SuppliedSharkDolphin {
 const string Root="Assets/UnderwaterArt/SuppliedSharkDolphin/";
 public static void RunAndCapture(){Run();var mat=AssetDatabase.LoadAssetAtPath<Material>(Root+"Dolphin/Skin.mat");string textures=Root+"Dolphin/textures/LPP_TT_checker_2048x2048_UV_GRID_";mat.SetTexture("_BumpMap",AssetDatabase.LoadAssetAtPath<Texture2D>(textures+"Normal.png"));mat.SetTexture("_RoughnessMap",AssetDatabase.LoadAssetAtPath<Texture2D>(textures+"Roughness.png"));mat.SetFloat("_UseRoughnessMap",1);mat.SetTexture("_OcclusionMap",AssetDatabase.LoadAssetAtPath<Texture2D>(textures+"AO.png"));EditorUtility.SetDirty(mat);AssetDatabase.SaveAssets();Capture();}
 static Vector3[] Points(Renderer r){if(r is SkinnedMeshRenderer s){return OctopusRepairValidation.Points(s);}return r.GetComponent<MeshFilter>().sharedMesh.vertices.Select(p=>r.transform.TransformPoint(p)).ToArray();}
 static Bounds BoundsOf(Transform root,Renderer[] renderers){bool first=true;Bounds b=default;foreach(var r in renderers)foreach(var p in Points(r)){var q=root.InverseTransformPoint(p);if(first){b=new Bounds(q,Vector3.zero);first=false;}else b.Encapsulate(q);}return b;}
 static Material MaterialFor(string kind,string slot){bool eye=kind=="Shark"?slot.StartsWith("Material."):slot.EndsWith(".001");string path=Root+kind+"/"+(eye?"Eyes":"Skin")+".mat";var mat=AssetDatabase.LoadAssetAtPath<Material>(path);if(mat)return mat;mat=new Material(Shader.Find("Underwater/Imported Marine Skin"));mat.name=kind+(eye?" eyes":" skin");mat.color=eye?new Color(.025f,.03f,.035f):Color.white;mat.enableInstancing=true;if(!eye)mat.mainTexture=AssetDatabase.LoadAssetAtPath<Texture2D>(Root+kind+"/textures/"+(kind=="Shark"?"Shark_Skin.jpeg":"LPP_TT_checker_2048x2048_UV_GRID_BaseColor.png"));if(mat.HasProperty("_Glossiness"))mat.SetFloat("_Glossiness",eye?.55f:.3f);AssetDatabase.CreateAsset(mat,path);return mat;}
 static AnimationClip ImportReduced(string kind){string path=Root+kind+"/"+kind+".fbx";var imp=(ModelImporter)AssetImporter.GetAtPath(path);imp.animationType=ModelImporterAnimationType.Legacy;imp.importAnimation=true;imp.isReadable=true;imp.importCameras=false;imp.importLights=false;imp.animationCompression=ModelImporterAnimationCompression.Off;var clips=imp.defaultClipAnimations;foreach(var c in clips){c.loopTime=true;c.wrapMode=WrapMode.Loop;}imp.clipAnimations=clips;imp.SaveAndReimport();return AssetDatabase.LoadAllAssetsAtPath(path).OfType<AnimationClip>().Single(c=>!c.name.StartsWith("__"));}
 static void SharkWaterAudio(){const int rate=22050,n=rate*8;var random=new System.Random(472);double smooth=0;using(var w=new BinaryWriter(File.Create("Assets/Ocean/Resources/SharkNearbySwim.wav"))){w.Write(System.Text.Encoding.ASCII.GetBytes("RIFF"));w.Write(36+n*2);w.Write(System.Text.Encoding.ASCII.GetBytes("WAVEfmt "));w.Write(16);w.Write((short)1);w.Write((short)1);w.Write(rate);w.Write(rate*2);w.Write((short)2);w.Write((short)16);w.Write(System.Text.Encoding.ASCII.GetBytes("data"));w.Write(n*2);for(int i=0;i<n;i++){double t=(double)i/rate;smooth=smooth*.94+(random.NextDouble()*2-1)*.06;double envelope=Math.Pow(Math.Sin(Math.PI*i/(n-1)),2);w.Write((short)(smooth*(.16+.08*Math.Sin(t*Math.PI))*envelope*32767));}}AssetDatabase.ImportAsset("Assets/Ocean/Resources/SharkNearbySwim.wav");}
 public static void Run(){
  AssetDatabase.Refresh();SharkWaterAudio();var clips=new Dictionary<string,AnimationClip>();foreach(var kind in new[]{"Shark","Dolphin"}){foreach(var path in AssetDatabase.FindAssets("t:Texture2D",new[]{Root+kind+"/textures"}).Select(AssetDatabase.GUIDToAssetPath)){var ti=(TextureImporter)AssetImporter.GetAtPath(path);ti.maxTextureSize=1024;ti.mipmapEnabled=true;ti.isReadable=false;if(path.Contains("Normal"))ti.textureType=TextureImporterType.NormalMap;ti.SaveAndReimport();}clips[kind]=ImportReduced(kind);}
  var scene=EditorSceneManager.OpenScene("Assets/Scenes/Underwater_Realistic.unity");var actors=UnityEngine.Object.FindObjectsByType<SeaLife>(FindObjectsSortMode.None).Where(a=>a.kind=="Dolphin"||a.kind=="Reef shark").ToArray();if(actors.Length!=4)throw new Exception("Expected shark and three dolphins");
  foreach(var actor in actors){string kind=actor.kind=="Dolphin"?"Dolphin":"Shark";var old=actor.GetComponentsInChildren<Renderer>().Where(r=>r.enabled&&(r is SkinnedMeshRenderer||r is MeshRenderer)).ToArray();var before=BoundsOf(actor.transform,old);foreach(var r in old)r.enabled=false;foreach(var a in actor.GetComponentsInChildren<Animation>())a.enabled=false;foreach(var a in actor.GetComponentsInChildren<ReefImportedAnimation>())a.enabled=false;foreach(var a in actor.GetComponentsInChildren<SharkBodyMotion>())a.enabled=false;
   var wrapper=new GameObject("Supplied animated "+kind);wrapper.transform.SetParent(actor.transform,false);wrapper.transform.SetAsFirstSibling();var model=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(Root+kind+"/"+kind+".fbx"));model.transform.SetParent(wrapper.transform,false);PrefabUtility.UnpackPrefabInstance(model,PrefabUnpackMode.Completely,InteractionMode.AutomatedAction);var player=model.GetComponent<Animation>();if(!player)player=model.AddComponent<Animation>();player.AddClip(clips[kind],clips[kind].name);player.clip=clips[kind];player.wrapMode=WrapMode.Loop;player.playAutomatically=false;player.cullingType=AnimationCullingType.AlwaysAnimate;clips[kind].SampleAnimation(model,0);
   var renderers=model.GetComponentsInChildren<Renderer>();var initial=BoundsOf(actor.transform,renderers);Debug.Log("SUPPLIED_SCALE "+kind+" old="+before+" initial="+initial);wrapper.transform.localScale=Vector3.one*(before.size.z/initial.size.z);wrapper.transform.localPosition=before.center-BoundsOf(actor.transform,renderers).center;
   foreach(var r in renderers){r.sharedMaterials=r.sharedMaterials.Select(m=>MaterialFor(kind,m?m.name:"")).ToArray();r.shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.Off;r.receiveShadows=false;}
   var playback=model.AddComponent<ReefImportedAnimation>();playback.distanceClock=true;playback.travelActor=actor.transform;playback.referenceTravelSpeed=kind=="Shark"?1.05f:(actor.GetComponent<DolphinSwimController>().compactPatrol?actor.GetComponent<DolphinSwimController>().compactSpeed:actor.GetComponent<DolphinSwimController>().referenceSpeed);playback.speed=1;playback.minimumTravelRate=.25f;playback.cycleOffset=kind=="Dolphin"?actor.GetComponent<DolphinSwimController>().podIndex/3f:0;
   var dolphin=actor.GetComponent<DolphinSwimController>();if(dolphin){dolphin.animationPlayer=player;dolphin.skin=model.GetComponentsInChildren<SkinnedMeshRenderer>().OrderByDescending(s=>s.sharedMesh.vertexCount).First();dolphin.suppliedSwim=playback;EditorUtility.SetDirty(dolphin);}
   bool first=true;Bounds envelope=default;var skinBounds=new Dictionary<SkinnedMeshRenderer,Bounds>();foreach(var skin in model.GetComponentsInChildren<SkinnedMeshRenderer>())skinBounds[skin]=default;
   for(int sample=0;sample<=64;sample++){clips[kind].SampleAnimation(model,clips[kind].length*sample/64);foreach(var r in renderers){bool skinFirst=sample==0;var skin=r as SkinnedMeshRenderer;Bounds sb=skin?skinBounds[skin]:default;foreach(var p in Points(r)){var local=actor.transform.InverseTransformPoint(p);if(first){envelope=new Bounds(local,Vector3.zero);first=false;}else envelope.Encapsulate(local);if(skin){var q=(skin.rootBone?skin.rootBone:skin.transform).InverseTransformPoint(p);if(skinFirst){sb=new Bounds(q,Vector3.zero);skinFirst=false;}else sb.Encapsulate(q);}}if(skin)skinBounds[skin]=sb;}}
   foreach(var pair in skinBounds){var b=pair.Value;b.Expand(b.size.magnitude*.08f);pair.Key.localBounds=b;pair.Key.updateWhenOffscreen=false;}clips[kind].SampleAnimation(model,0);envelope.Expand(.08f);var clearance=actor.GetComponent<ReefAnimalClearance>();clearance.animatedBody=envelope;clearance.Enforce();EditorUtility.SetDirty(clearance);var encounter=actor.GetComponent<ReefEncounter>();if(encounter)encounter.skin=renderers;
   var source=actor.gameObject.AddComponent<AudioSource>();source.playOnAwake=false;var audio=actor.gameObject.AddComponent<FeaturedCreatureAudio>();audio.clip=Resources.Load<AudioClip>(kind=="Dolphin"?"DolphinNearby":"SharkNearbySwim");if(!audio.clip)throw new Exception("Missing nearby audio");Debug.Log("SUPPLIED_INSTALLED "+kind+" bounds="+envelope+" clip="+clips[kind].length+" audio="+audio.clip.name);
  }
  EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();Validate();
 }
 public static void Validate(){EditorSceneManager.OpenScene("Assets/Scenes/Underwater_Realistic.unity");Physics.SyncTransforms();foreach(var a in UnityEngine.Object.FindObjectsByType<SeaLife>(FindObjectsSortMode.None).Where(a=>a.kind=="Dolphin"||a.kind=="Reef shark")){
  var model=a.transform.GetChild(0).GetChild(0).gameObject;var player=model.GetComponent<Animation>();if(!player||!player.clip||!a.GetComponent<FeaturedCreatureAudio>().clip)throw new Exception("Missing supplied creature setup");var pos=a.transform.position;float travel=0;var visible=model.GetComponentsInChildren<Renderer>();var firstPose=visible.SelectMany(Points).ToArray();player.clip.SampleAnimation(model,.21f);var nextPose=visible.SelectMany(Points).ToArray();float deformation=firstPose.Zip(nextPose,(x,y)=>Vector3.Distance(x,y)).Max();if(deformation<.001f)throw new Exception("Static supplied animation");player.clip.SampleAnimation(model,0);Debug.Log("SUPPLIED_POSE "+a.kind+" deformation="+deformation);
  for(int i=0;i<1200;i++){var old=a.transform.position;if(a.kind=="Dolphin")a.GetComponent<WreckCreature>().Step(.05f);else a.GetComponent<OpenWaterShark>().Step(.05f,a.transform.position+Vector3.right*12,Vector3.zero,true);model.GetComponent<ReefImportedAnimation>().StepPlayback(.05f);travel+=Vector3.Distance(old,a.transform.position);}
  if(travel<.1f)throw new Exception("Creature movement stalled: "+a.name);Debug.Log("SUPPLIED_VALIDATED "+a.kind+" travel60Seconds="+travel+" animationRate="+model.GetComponent<ReefImportedAnimation>().CurrentRate+" spatialAudioRange=6");
 }Debug.Log("SUPPLIED_REPLACEMENT_PASSED");EditorSceneManager.OpenScene("Assets/Scenes/Underwater_Realistic.unity");}
 public static void Inspect(){
  foreach(var p in new[]{Root+"Shark/Shark.fbx",Root+"Dolphin/Dolphin.fbx"}){
   var imp=(ModelImporter)AssetImporter.GetAtPath(p);imp.animationType=ModelImporterAnimationType.Legacy;imp.importAnimation=true;imp.isReadable=true;imp.importCameras=false;imp.importLights=false;imp.SaveAndReimport();
   var model=AssetDatabase.LoadAssetAtPath<GameObject>(p);
   Debug.Log("SUPPLIED_INSPECT "+p+" clips="+string.Join(",",AssetDatabase.LoadAllAssetsAtPath(p).OfType<AnimationClip>().Select(c=>c.name+":"+c.length)));
   foreach(var r in model.GetComponentsInChildren<Renderer>())Debug.Log("SUPPLIED_RENDER "+r.name+" bounds="+r.bounds+" materials="+string.Join(",",r.sharedMaterials.Select(m=>m?m.name:"null")));
   Debug.Log("SUPPLIED_BONES "+string.Join(",",model.GetComponentsInChildren<Transform>().Select(t=>t.name)));
  }
 }
 public static void Capture(){
  Directory.CreateDirectory("Renders/SuppliedSharkDolphin/Unity");
  foreach(string kind in new[]{"Shark","Dolphin"}){
   EditorSceneManager.OpenScene("Assets/Scenes/Underwater_Realistic.unity");var actor=UnityEngine.Object.FindObjectsByType<SeaLife>(FindObjectsSortMode.None).First(a=>a.kind==(kind=="Shark"?"Reef shark":"Dolphin"));var model=actor.transform.GetChild(0).GetChild(0).gameObject;var player=model.GetComponent<Animation>();var skins=model.GetComponentsInChildren<SkinnedMeshRenderer>();
   var camera=new GameObject("Supplied asset review camera").AddComponent<Camera>();camera.cullingMask=1<<31;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(.025f,.08f,.12f);camera.nearClipPlane=.005f;camera.farClipPlane=100;camera.orthographic=true;RenderSettings.fog=false;RenderSettings.ambientLight=new Color(.7f,.75f,.8f);Shader.SetGlobalFloat("_ReefLight",1);
   var lamp=new GameObject("Review light").AddComponent<Light>();lamp.type=LightType.Directional;lamp.intensity=1.3f;lamp.transform.rotation=Quaternion.Euler(30,-35,0);
   for(int phase=0;phase<4;phase++){
    player.clip.SampleAnimation(model,phase*.21f);var bounds=BoundsOf(actor.transform,skins);var center=actor.transform.TransformPoint(bounds.center);float radius=bounds.extents.magnitude*actor.transform.lossyScale.x;camera.orthographicSize=radius*.83f;var proxies=new List<GameObject>();
    foreach(var skin in skins){var mesh=UnityEngine.Object.Instantiate(skin.sharedMesh);mesh.ClearBlendShapes();mesh.vertices=Points(skin);var normals=skin.sharedMesh.normals;var weights=skin.sharedMesh.boneWeights;var matrices=skin.bones.Select((b,i)=>b.localToWorldMatrix*skin.sharedMesh.bindposes[i]).ToArray();for(int i=0;i<normals.Length;i++){var n=normals[i];var w=weights[i];normals[i]=(matrices[w.boneIndex0].MultiplyVector(n)*w.weight0+matrices[w.boneIndex1].MultiplyVector(n)*w.weight1+matrices[w.boneIndex2].MultiplyVector(n)*w.weight2+matrices[w.boneIndex3].MultiplyVector(n)*w.weight3).normalized;}mesh.normals=normals;mesh.RecalculateBounds();var go=new GameObject("Review pose");go.layer=31;go.AddComponent<MeshFilter>().sharedMesh=mesh;go.AddComponent<MeshRenderer>().sharedMaterials=skin.sharedMaterials;proxies.Add(go);}
    var view=phase==1?actor.transform.right:phase==2?actor.transform.forward:actor.transform.right+actor.transform.forward+Vector3.up*.3f;camera.transform.position=center+view.normalized*radius*3;camera.transform.LookAt(center);ReefCorrectionAudit.Capture(camera,"Renders/SuppliedSharkDolphin/Unity/"+kind+"_"+phase+".png");foreach(var go in proxies){UnityEngine.Object.DestroyImmediate(go.GetComponent<MeshFilter>().sharedMesh);UnityEngine.Object.DestroyImmediate(go);}
   }
  }Debug.Log("SUPPLIED_CAPTURES_PASSED");
 }
}
